// 3Our Supermat API — validasi API key & normalisasi input untuk endpoint GENERATE
// Key dibaca dari env n8n SUPERMAT_API_KEYS (pisah koma) bila ada, kalau tidak pakai daftar di bawah.
// Key asli HANYA diisi di node n8n (jangan di-commit). Placeholder di bawah wajib diganti setelah import.
const DEFAULT_KEYS = ['GANTI-DENGAN-KEY-RAHASIA'];
let keys = DEFAULT_KEYS;
try { const e = String($env.SUPERMAT_API_KEYS || '').trim(); if (e) keys = e.split(',').map(s => s.trim()).filter(Boolean); } catch (err) { /* env access diblokir -> pakai default */ }

const headers = $json.headers || {};
const body = $json.body || {};
const bearer = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
const key = String(headers['x-supermat-key'] || headers['x-api-key'] || bearer || body.apiKey || '').trim();
const ok = !!key && keys.includes(key);

const keyword = String(body.keyword || body.query || '').trim();
let statusCode = 200, error = '';
if (!ok) { statusCode = 401; error = 'API key tidak valid. Kirim header X-Supermat-Key.'; }
else if (!keyword) { statusCode = 400; error = 'Field "keyword" wajib diisi.'; }

return [{ json: {
  ok: statusCode === 200, statusCode, error,
  keyword,
  geo: String(body.Geo || body.geo || 'ID').toUpperCase(),
  ln: String(body.Ln || body.ln || 'id').toLowerCase(),
  clientName: String(body.Client_Name || body.clientName || body.brandName || 'Brand Anda').trim(),
  niche: String(body.niche || '').trim(),
  tone: String(body.tone || '').trim(),
  wordCount: Math.min(Math.max(Number(body.wordCount) || 800, 400), 1500),
  requestId: String(body.requestId || ('req_' + Date.now().toString(36))),
} }];

// Pilih kandidat keyword dari Google Trends (rising + top) yang masih relevan dengan seed keyword.
// Seed keyword SELALU jadi kandidat pertama, jadi alur tidak pernah mati walau Trends kosong/error.
const N = $('Auth & Normalize').first().json;
let t = {}; try { t = $('Riset Google Trends').first().json || {}; } catch (e) {}
const ac = $input.first().json || {}; // SerpAPI google_autocomplete
const rq = t.related_queries || {};
const pool = [
  ...(rq.rising || []), ...(rq.top || []),
].map(x => String(x.query || '').trim()).concat((ac.suggestions || []).map(s => String(s.value || '').trim())).filter(Boolean);

const seed = N.keyword.toLowerCase();
const stop = new Set(['di', 'ke', 'dari', 'yang', 'dan', 'untuk', 'dengan', 'ada', 'adalah', 'itu', 'ini', 'cara', 'tips', 'info', 'the', 'a', 'an', 'of', 'for', 'in', 'on', 'to']);
const terms = [seed, ...seed.split(/\s+/).map(w => w.replace(/[^a-z0-9]/g, '')).filter(w => w.length > 2 && !stop.has(w))];
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const matches = q => terms.some(tm => tm.includes(' ') ? q.includes(tm) : new RegExp('\\b' + esc(tm) + '\\b', 'i').test(q));

const matched = pool.filter(q => q.toLowerCase() !== seed && matches(q.toLowerCase()));
const uniq = [...new Set([N.keyword, ...matched])].slice(0, 4);
return uniq.map((q, i) => ({ json: { query: q, isSeed: i === 0, source: i === 0 ? 'seed' : 'trends/autocomplete', trendsError: t.error ? String(t.error.message || t.error) : '' } }));

// Gabungkan metrik Ahrefs (RapidAPI) per kandidat, pilih target keyword terbaik.
// Prioritas: volume terbesar dengan difficulty valid; fallback: seed keyword tanpa metrik.
const N = $('Auth & Normalize').first().json;
const cands = $('Pilih Kandidat').all().map(i => i.json);
const metrics = $input.all().map(i => i.json || {});
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

const rows = cands.map((c, i) => {
  const m = metrics[i] || {}; const d = m.data || m || {};
  const diffRaw = d.difficulty;
  return {
    query: c.query, isSeed: !!c.isSeed,
    searchVolume: num(d.globalSearchVolume ?? d.searchVolume ?? d.volume),
    difficulty: (diffRaw === null || diffRaw === undefined || diffRaw === 'null' || diffRaw === '') ? null : num(diffRaw),
    trafficPotential: num(d.trafficPotential),
    cpc: num(d.cpc),
    error: m.error ? String(m.error.message || m.error) : '',
  };
});
const valid = rows.filter(r => r.searchVolume > 0).sort((a, b) => b.searchVolume - a.searchVolume);
const seedRow = rows.find(r => r.isSeed) || { query: N.keyword, searchVolume: 0, difficulty: null, trafficPotential: 0 };
const best = valid[0] || seedRow;

return [{ json: {
  ...N,
  targetKeyword: best.query,
  searchVolume: best.searchVolume,
  difficulty: best.difficulty,
  trafficPotential: best.trafficPotential,
  seedMetrics: { searchVolume: seedRow.searchVolume, difficulty: seedRow.difficulty },
  candidates: rows,
  relatedQueries: rows.map(r => r.query).filter(q => q !== best.query),
  geoLower: String(N.geo || 'ID').toLowerCase(),
} }];

// Parse output AI Agent -> Unified Article Payload yang dikembalikan ke pemanggil API.
const T = $('Tentukan Target').first().json;
const ai = $input.first().json || {};

function safeParse(str) {
  if (!str) return null;
  if (typeof str === 'object') return str;
  const s = String(str);
  try { return JSON.parse(s); } catch (e) {}
  const clean = s.replace(/```json/gi, '').replace(/```/g, '').trim();
  const a = clean.indexOf('{'), b = clean.lastIndexOf('}');
  if (a >= 0 && b > a) { try { return JSON.parse(clean.slice(a, b + 1)); } catch (e) {} }
  return null;
}
const raw = ai.output ?? ai.text ?? ai;
const parsed = safeParse(raw) || {};

const slugify = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 90);
const title = String(parsed.title || '').trim();
const body = String(parsed.body || parsed.bodyMarkdown || parsed.content || '').trim();
if (!title || !body) {
  return [{ json: { ok: false, statusCode: 502, error: 'AI tidak mengembalikan artikel yang valid. Coba lagi.', raw: typeof raw === 'string' ? raw.slice(0, 500) : raw, requestId: T.requestId } }];
}
const excerpt = String(parsed.excerpt || body.replace(/[#*_>`-]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 160)).trim();
const words = body.split(/\s+/).filter(Boolean).length;
const keywords = [...new Set([T.targetKeyword, T.keyword, ...(T.relatedQueries || [])].filter(Boolean))].slice(0, 8);

return [{ json: {
  ok: true, statusCode: 200,
  status: 'ok',
  requestId: T.requestId,
  keyword: T.keyword,
  clientName: T.clientName,
  geo: T.geo, ln: T.ln,
  article: {
    title,
    slug: slugify(parsed.slug) || slugify(title),
    excerpt,
    bodyMarkdown: body,
    keywords,
    primaryKeyword: T.targetKeyword,
    searchVolume: T.searchVolume,
    difficulty: T.difficulty,
    trafficPotential: T.trafficPotential,
    wordCount: words,
    language: T.ln,
    generatedAt: new Date().toISOString(),
    model: 'gemini',
  },
  research: { candidates: T.candidates, relatedQueries: T.relatedQueries },
} }];

// 3Our Supermat API — validasi API key & normalisasi input untuk endpoint PUBLISH
// Body: { cmsType: 'wordpress'|'wix'|'sanity', action: 'draft'|'publish', cms: {...kredensial user...}, article: {...}, postId?: '' }
// Key asli HANYA diisi di node n8n (jangan di-commit). Placeholder di bawah wajib diganti setelah import.
const DEFAULT_KEYS = ['GANTI-DENGAN-KEY-RAHASIA'];
let keys = DEFAULT_KEYS;
try { const e = String($env.SUPERMAT_API_KEYS || '').trim(); if (e) keys = e.split(',').map(s => s.trim()).filter(Boolean); } catch (err) {}

const headers = $json.headers || {};
const body = $json.body || {};
const bearer = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
const key = String(headers['x-supermat-key'] || headers['x-api-key'] || bearer || body.apiKey || '').trim();
const ok = !!key && keys.includes(key);

const cmsType = String(body.cmsType || body.CMS_Type || '').toLowerCase().trim();
const action = String(body.action || '').toLowerCase() === 'publish' ? 'publish' : 'draft';
const cmsIn = body.cms || {};
const str = v => String(v ?? '').trim();
const cms = {
  wordpress: {
    url: str((cmsIn.wordpress || {}).url || body.wpUrl).replace(/\/+$/, ''),
    user: str((cmsIn.wordpress || {}).user || body.wpUser),
    appPassword: str((cmsIn.wordpress || {}).appPassword || body.wpPass),
  },
  wix: {
    siteId: str((cmsIn.wix || {}).siteId || body.wixSiteId),
    apiKey: str((cmsIn.wix || {}).apiKey || body.wixKey),
    memberId: str((cmsIn.wix || {}).memberId || body.wixMemberId),
  },
  sanity: {
    projectId: str((cmsIn.sanity || {}).projectId || body.projectId),
    dataset: str((cmsIn.sanity || {}).dataset || body.dataset) || 'production',
    token: str((cmsIn.sanity || {}).token || body.authToken),
    studioUrl: str((cmsIn.sanity || {}).studioUrl || body.studioUrl),
  },
};
const article = body.article && typeof body.article === 'object' ? body.article : null;
const postId = str(body.postId || body.draftDocId || body.draftPostId);

let statusCode = 200, error = '';
if (!ok) { statusCode = 401; error = 'API key tidak valid. Kirim header X-Supermat-Key.'; }
else if (!['wordpress', 'wix', 'sanity'].includes(cmsType)) { statusCode = 400; error = 'cmsType harus wordpress, wix, atau sanity.'; }
else if (!article && !postId) { statusCode = 400; error = 'Field "article" wajib diisi (atau postId untuk publish draf yang sudah ada).'; }
else if (article && (!str(article.title) || !str(article.bodyMarkdown || article.body))) { statusCode = 400; error = 'article.title dan article.bodyMarkdown wajib diisi.'; }
else if (cmsType === 'wordpress' && (!cms.wordpress.url || !cms.wordpress.user || !cms.wordpress.appPassword)) { statusCode = 400; error = 'Kredensial WordPress belum lengkap (url, user, appPassword).'; }
else if (cmsType === 'wix' && (!cms.wix.siteId || !cms.wix.apiKey)) { statusCode = 400; error = 'Kredensial Wix belum lengkap (siteId, apiKey).'; }
else if (cmsType === 'sanity' && (!cms.sanity.projectId || !cms.sanity.token)) { statusCode = 400; error = 'Kredensial Sanity belum lengkap (projectId, token).'; }
if (cms.wordpress.url && !/^https?:\/\//i.test(cms.wordpress.url)) cms.wordpress.url = 'https://' + cms.wordpress.url;

return [{ json: {
  ok: statusCode === 200, statusCode, error,
  cmsType, action, cms, postId,
  article: article ? Object.assign({}, article, { bodyMarkdown: str(article.bodyMarkdown || article.body) }) : null,
  clientName: str(body.clientName || body.Client_Name || 'Brand Anda'),
  // kompatibilitas adapter Sanity lama
  projectId: cms.sanity.projectId, authToken: cms.sanity.token, draftDocId: cmsType === 'sanity' ? postId : '',
  telegramChatId: '',
  requestId: str(body.requestId) || ('pub_' + Date.now().toString(36)),
} }];

// Samakan format hasil adapter + tentukan HTTP code
const r = $input.first().json || {};
const ok = r.status === 'ok' || r.status === 'success';
return [{ json: {
  status: ok ? 'ok' : 'error',
  statusCode: ok ? 200 : (r.httpStatus && r.httpStatus >= 400 && r.httpStatus < 500 ? 400 : 502),
  cmsType: r.cmsType || $('Auth & Normalize (Publish)').first().json.cmsType,
  action: r.action || $('Auth & Normalize (Publish)').first().json.action,
  postId: r.postId || r.draftDocId || '',
  postStatus: r.postStatus || (ok ? ($('Auth & Normalize (Publish)').first().json.action === 'publish' ? 'publish' : 'draft') : ''),
  draftEditUrl: r.draftEditUrl || '',
  publicUrl: r.publicUrl || '',
  previewUrl: r.previewUrl || '',
  title: r.title || '',
  message: r.message || (ok ? 'Berhasil.' : 'Gagal mengirim ke CMS.'),
  requestId: r.requestId || $('Auth & Normalize (Publish)').first().json.requestId,
} }];
